function employeeEditForm(id){const e=person(id);form(lawText('تعديل بيانات الموظف','Edit employee profile'),'<input type="hidden" name="id" value="'+e.id+'"><div class="form-grid">'+field(lawText('الاسم','Name'),'name','text',e.name)+field(lawText('البريد','Email'),'email','email',e.email)+field(lawText('المسمى الوظيفي','Job title'),'job','text',e.job)+field(lawText('القسم','Department'),'department','text',e.department)+selectField(lawText('المدير المباشر','Line manager'),'manager',[{value:'',label:lawText('غير محدد','Unassigned')},...state.employees.filter(x=>x.id!==e.id&&x.status!=='inactive').map(x=>({value:x.id,label:x.name}))],e.manager)+field(lawText('الراتب الأساسي','Basic salary'),'salary','number',e.salary,'min="0"')+field(lawText('البدلات','Allowances'),'allowance','number',e.allowance,'min="0"')+field(lawText('المكافآت الشهرية','Monthly bonus'),'bonus','number',e.bonus,'min="0"')+field(lawText('الخصومات الشهرية','Monthly deductions'),'deduction','number',e.deduction,'min="0"')+field(lawText('الرصيد السنوي الكلي','Total annual leave allowance'),'leaveBalance','number',e.leaveBalance,'min="0"')+'</div><p>'+lawText('تعديل الراتب يخص الكشوف الجديدة. كشف الشهر المجهز يُعدَّل من صفحة الرواتب قبل الاعتماد.','Salary changes apply to future drafts. Edit an existing month from Payroll before approval.')+'</p>','employeeEdit');}
function accessSettingsCard(){return '<div style="margin-top:20px">'+card(lawText('الحسابات والأدوار','Accounts & roles'),lawText('صلاحيات العمل من الواجهة؛ لا يحتاج المستخدم فتح Sheets','Manage permissions here. Users never need to open Sheets.'),table([lawText('البريد','Email'),lawText('الدور','Role')],(state.access||[]).map(a=>'<tr><td class="mono">'+esc(a.email)+'</td><td>'+esc(a.role)+'</td></tr>')),btn(lawText('＋ إضافة / تعديل دور','＋ Add / update role'),'accessForm','','primary'))+'</div>';}
function accessForm(email=''){if(role!=='admin')return;const assigned=(state.access||[]).find(a=>a.email.toLowerCase()===email.toLowerCase());form(lawText('إدارة حساب مستخدم','Manage user access'),field(lawText('بريد الموظف داخل الشركة','Employee company email'),'email','email',email)+selectField(lawText('الدور','Role'),'role',[{value:'employee',label:lawText('موظف','Employee')},{value:'manager',label:lawText('مدير مباشر','Line manager')},{value:'hr',label:'HR'},{value:'finance',label:lawText('المالية','Finance')},{value:'admin',label:lawText('مسؤول النظام','Administrator')}],assigned?.role||'employee')+'<p>'+lawText('الدخول الحقيقي بحساب Google Workspace. لا نخزن كلمات مرور. اربط بريد الموظف بملفه، وحدد المدير من تعديل بيانات الموظف.','Real sign-in uses Google Workspace. No passwords are stored. Link the employee email to their profile and assign their manager in the profile editor.')+'</p>','access');}
function payrollRowForm(id){const run=state.payroll.find(r=>r.month===month),row=run?.rows.find(r=>r.employeeId===id);if(!row)return;form(lawText('تعديل بند راتب','Edit payroll inputs')+' • '+esc(row.name),'<input type="hidden" name="runId" value="'+run.id+'"><input type="hidden" name="employeeId" value="'+id+'"><div class="form-grid">'+field(lawText('الأساسي','Basic'),'basic','number',row.basic,'min="0"')+field(lawText('البدلات','Allowances'),'allowance','number',row.allowance,'min="0"')+field(lawText('المكافآت','Bonus'),'bonus','number',row.bonus,'min="0"')+field(lawText('الخصومات','Deductions'),'deduction','number',row.deduction,'min="0"')+'</div><p>'+lawText('هذا التعديل يخص الشهر المحدد فقط، ويحتاج اعتماد المالية بعد المراجعة.','This edit affects this month only and requires Finance approval after review.')+'</p>','payrollRow');}
